  1	/**
  2	 * The tracing worker: owns the engines and the loaded image.
  3	 *
  4	 * The vtracer sessions are long-lived on purpose. vtracer caches its segmentation inside
  5	 * the session and only re-clusters when a clustering-relevant parameter changes, so
  6	 * repeated renders while the user drags a slider are cheap. potrace has no equivalent, so
  7	 * it keeps the raw `ImageData` around and re-traces from scratch each time.
  8	 *
  9	 * Note there is no cancellation here. GitHub Pages cannot send COOP/COEP headers, so
 10	 * `SharedArrayBuffer` is unavailable and a worker blocked inside wasm cannot observe an
 11	 * incoming message. The UI keeps at most one render in flight instead; see `client.ts`.
 12	 */
 13	
 14	import init, { TraceSession, defaultConfig } from '#lib/wasm/vectrace.js';
 15	import wasmUrl from '#lib/wasm/vectrace_bg.wasm?url';
 16	import { trace as potraceTrace } from '#lib/engines/potrace';
 17	import { binarize, type BinarizeMode } from '#lib/image/binarize';
 18	import { optimizeSvg } from '#lib/svg/optimize';
 19	import type { PresetName, RenderTarget, TraceOutput, TraceParams } from '#lib/engines/types';
 20	import type { Request, Response } from './protocol';
 21	
 22	const post = (m: Response) => self.postMessage(m);
 23	
 24	/**
 25	 * One entry per resolution.
 26	 *
 27	 * `source` is the decoded image; `image` is what the engines actually see, which differs
 28	 * once preprocessing is on. The vtracer session is built from `image`, so it has to be
 29	 * rebuilt whenever the preprocessing settings change — `key` records what it was built
 30	 * from so unrelated parameter changes still hit the cache.
 31	 */
 32	interface Loaded {
 33		source: ImageData;
 34		image: ImageData;
 35		session: TraceSession;
 36		key: string;
 37	}
 38	
 39	let full: Loaded | null = null;
 40	let preview: Loaded | null = null;
 41	
 42	const ready = init({ module_or_path: wasmUrl }).then(() => {
 43		post({ type: 'ready', version: '1.0.0-alpha.3' });
